def verifier(assign):
    # Recompute x, y from hidden parameters; verify the identity numerically; then return minimal k = lcm(denominators of x and y)
    import math
    from fractions import Fraction
    from math import gcd

    # Check required fields
    required = ['alpha','L','m','A1','A0','B1','D0','p','q','alpha_num','alpha_den','beta_num','beta_den']
    for key in required:
        if key not in assign:
            # Missing field
            return (False, None)
        if not isinstance(assign[key], int):
            return (False, None)
    L = assign['L']; m = assign['m']; A1 = assign['A1']; A0 = assign['A0']; B1 = assign['B1']; D0 = assign['D0']
    p = assign['p']; q = assign['q']
    alpha_num = assign['alpha_num']; alpha_den = assign['alpha_den']
    beta_num = assign['beta_num']; beta_den = assign['beta_den']

    # Domain sanity
    if m <= 1 or L <= 0 or D0 <= 0 or q <= 1 or p <= 0 or p >= q:
        return (False, None)

    # Build rationals
    s = Fraction(p, q)
    alpha = Fraction(alpha_num, alpha_den)
    beta = Fraction(beta_num, beta_den)

    # Construct x and y
    x = (Fraction(1, 1) - s * s) / m
    t = alpha + beta * s
    if not (Fraction(0, 1) < t < Fraction(1, 1)):
        return (False, None)
    y = (Fraction(1, 1) - t * t) / m

    # Check positivity ranges
    if not (Fraction(0, 1) < x < Fraction(1, m)):
        return (False, None)
    if not (Fraction(0, 1) < y < Fraction(1, m)):
        return (False, None)

    # Numeric verification of identity
    def cbrt(z):
        return math.copysign(abs(z) ** (1.0 / 3.0), z)
    xf = float(x)
    yf = float(y)
    try:
        lhs = L + math.sqrt(max(0.0, 1 - m * yf))
        S = L ** 3 + xf ** 2
        sqrt_term = math.sqrt(9 * (S ** 2) + (4.0 / 3.0) * (xf ** 6) / (L ** 3))
        Ux = cbrt(S / 2.0 + sqrt_term / 6.0) + cbrt(S / 2.0 - sqrt_term / 6.0)
        rhs = yf + (A1 * xf + A0 + B1 * math.sqrt(max(0.0, 1 - m * xf))) / D0 + Ux
    except Exception:
        return (False, None)

    if not (abs(Ux - L) < 1e-9 and abs(lhs - rhs) < 1e-8):
        # Identity failed; reject instance
        return (False, None)

    # Difficulty enforcement: denominators must be moderately large
    x_den = x.denominator
    y_den = y.denominator
    if x_den < 20 or y_den < 20:
        return (False, None)

    # Minimal k is lcm of denominators of x and y in lowest terms
    def lcm(a, b):
        return a // gcd(a, b) * b
    k = lcm(x_den, y_den)

    return (True, k)
